def run_agent(prompt, temperature=0.7):
    # sampling means repeated calls diverge
    return llm(prompt, temperature=temperature)

prompt = "Give me a slogan for a coffee shop."
for _ in range(3):
    print(run_agent(prompt))
# 'Wake up and smell the ambition.'
# 'Your daily grind, perfected.'
# 'Life happens, coffee helps.'
# one run proves nothing -> measure over many runs and cases
